const now = Date.now();
const maxAgeMs = 1000 * 60 * 60 * 72;

function hostnameFromUrl(value) {
  try {
    return new URL(value).hostname.replace(/^www\./, '');
  } catch {
    return 'Unknown Source';
  }
}

function cleanText(value, max = 500) {
  return String(value ?? '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, max);
}

const output = [];
for (const item of $input.all().map((entry) => entry.json)) {
  if (item.error) continue;

  const link = String(item.link || item.guid || item.id || '').trim();
  const title = cleanText(item.title, 200);
  const excerpt = cleanText(item.contentSnippet || item.content || item.summary || item.description || '', 600);
  const published = item.isoDate || item.pubDate || item.published || item.created || '';
  const publishedTs = published ? Date.parse(published) : NaN;
  const source = cleanText(item.creator || item.feedTitle || hostnameFromUrl(link), 80) || 'Unknown Source';
  const publishedAt = Number.isNaN(publishedTs) ? '' : new Date(publishedTs).toISOString();

  if (!title || !link) continue;
  if (title.length < 20) continue;
  if (excerpt.length < 40 && title.length < 45) continue;
  if (publishedAt && Date.parse(publishedAt) < now - maxAgeMs) continue;

  output.push({
    json: {
      title,
      link,
      excerpt,
      published_at: publishedAt,
      source,
      age_hours: Number.isNaN(publishedTs) ? 999 : Math.max(0, Math.round((now - publishedTs) / 36e5)),
    },
  });
}

return output;

const articles = $input.all().map((item) => item.json);

function normalizeTitle(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function canonicalLink(value) {
  try {
    const url = new URL(String(value || '').trim());
    url.hash = '';
    const keys = [];
    url.searchParams.forEach((_, key) => {
      if (key.toLowerCase().startsWith('utm_')) keys.push(key);
    });
    for (const key of keys) url.searchParams.delete(key);
    return url.toString();
  } catch {
    return String(value || '').trim();
  }
}

function keywordScore(article) {
  const haystack = `${article.title} ${article.excerpt}`.toLowerCase();
  const keywords = ['ai', 'artificial intelligence', 'llm', 'agent', 'model', 'openai', 'anthropic', 'google', 'meta', 'microsoft', 'nvidia', 'research'];
  let score = 0;
  for (const keyword of keywords) {
    if (haystack.includes(keyword)) score += 2;
  }
  return score;
}

const unique = [];
const seen = new Set();
for (const article of articles) {
  const titleKey = normalizeTitle(article.title);
  const linkKey = canonicalLink(article.link);
  const dedupeKey = `${titleKey}::${linkKey}`;
  if (!titleKey || !linkKey || seen.has(dedupeKey) || seen.has(titleKey) || seen.has(linkKey)) continue;
  seen.add(dedupeKey);
  seen.add(titleKey);
  seen.add(linkKey);

  const uniqueArticle = {
    title: article.title,
    link: article.link,
    excerpt: article.excerpt,
    published_at: article.published_at,
    source: article.source,
    age_hours: article.age_hours,
    canonical_link: linkKey,
  };
  unique.push(uniqueArticle);
}

const scored = [];
for (const article of unique) {
  const recencyBoost = article.age_hours <= 12 ? 10 : article.age_hours <= 24 ? 7 : article.age_hours <= 48 ? 4 : 1;
  const substanceBoost = Math.min(6, Math.floor((article.excerpt || '').length / 90));
  scored.push({
    title: article.title,
    link: article.link,
    excerpt: article.excerpt,
    published_at: article.published_at,
    source: article.source,
    age_hours: article.age_hours,
    canonical_link: article.canonical_link,
    score: recencyBoost + substanceBoost + keywordScore(article),
  });
}

scored.sort((a, b) => b.score - a.score || a.age_hours - b.age_hours);

const topStories = [];
const sourceCounts = new Map();
for (const article of scored) {
  const count = sourceCounts.get(article.source) || 0;
  if (count >= 2) continue;
  sourceCounts.set(article.source, count + 1);
  topStories.push({
    title: article.title,
    source: article.source,
    excerpt: article.excerpt,
    published_at: article.published_at,
    link: article.link,
    canonical_link: article.canonical_link,
    score: article.score,
  });
  if (topStories.length >= 5) break;
}

const runDate = new Date().toISOString().slice(0, 10);
const blobParts = [];
for (let index = 0; index < topStories.length; index++) {
  const story = topStories[index];
  blobParts.push([
    `${index + 1}. ${story.title}`,
    `Source: ${story.source}`,
    `Published: ${story.published_at || 'Unknown'}`,
    `Excerpt: ${story.excerpt || 'No excerpt provided.'}`,
    `Link: ${story.canonical_link}`,
  ].join('\n'));
}

const result = {
  run_date: runDate,
  story_count: topStories.length,
  stories: topStories,
  story_blob: blobParts.join('\n\n'),
};

return [{ json: result }];

const source = $input.first().json;
const originalStories = Array.isArray(source.stories) ? source.stories : [];
const raw = String(source.text ?? source.output ?? source.response ?? source.message ?? '').trim();

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function truncate(value, max) {
  const text = String(value ?? '').replace(/\s+/g, ' ').trim();
  if (text.length <= max) return text;
  return `${text.slice(0, Math.max(0, max - 1)).trim()}…`;
}

function extractJson(text) {
  if (!text) return null;
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
  const jsonCandidate = fenced?.[1]?.trim() || text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1).trim();
  if (!jsonCandidate || !jsonCandidate.startsWith('{')) return null;
  return JSON.parse(jsonCandidate);
}

function makeStory(baseStory, aiStory, index) {
  return {
    title: String(aiStory?.title || baseStory?.title || `Story ${index + 1}`).trim(),
    source: String(aiStory?.source || baseStory?.source || 'Unknown Source').trim(),
    summary: truncate(aiStory?.summary || baseStory?.excerpt || 'No summary available.', 220),
    why_it_matters: truncate(aiStory?.why_it_matters || 'This is one of the more relevant AI updates from today.', 160),
    link: String(aiStory?.link || baseStory?.canonical_link || baseStory?.link || '').trim(),
  };
}

let parsed = null;
try {
  parsed = extractJson(raw);
} catch {
  parsed = null;
}

const formattedStories = [];
if (Array.isArray(parsed?.stories) && parsed.stories.length) {
  for (let index = 0; index < parsed.stories.length && index < 5; index++) {
    formattedStories.push(makeStory(originalStories[index], parsed.stories[index], index));
  }
} else {
  for (let index = 0; index < originalStories.length && index < 5; index++) {
    formattedStories.push(makeStory(originalStories[index], null, index));
  }
}

const intro = truncate(parsed?.intro || 'Here are the strongest AI updates worth your attention today.', 180);
const headerDate = escapeHtml(source.run_date || new Date().toISOString().slice(0, 10));
const bodyParts = [];
for (let index = 0; index < formattedStories.length; index++) {
  const story = formattedStories[index];
  bodyParts.push([
    `<b>${index + 1}. ${escapeHtml(truncate(story.title, 110))}</b>`,
    `<i>${escapeHtml(truncate(story.source, 60))}</i>`,
    `${escapeHtml(story.summary)}`,
    `<b>Why it matters:</b> ${escapeHtml(story.why_it_matters)}`,
    `${escapeHtml(story.link)}`,
  ].join('\n'));
}

const message = (`<b>AI News Digest | ${headerDate}</b>\n${escapeHtml(intro)}\n\n${bodyParts.join('\n\n')}`).slice(0, 3900);
const result = {
  run_date: source.run_date,
  telegram_message: message,
  story_count: formattedStories.length,
  ai_model_used: 'groq/compound-mini',
};

return [{ json: result }];
